    name: 'Adjust contrast',
    h1: 'Adjust Image Contrast Online',
    tagline: 'A Contrast slider that pivots around middle gray, plus Tone and Curves when you want contrast without crushing the ends.',
    metaTitle: `Adjust Image Contrast Online: Slider, Tone or Curves | ${PHOTO_BRAND}`,
